            while m == r:
                m = rng.randint(1, n)
        a = [v for v in range(1, n + 1) if v != m] + [r]
        rng.shuffle(a)
        return str(n) + '\n' + ' '.join(map(str, a))
    tests = [make(2, 1, 2), make(2, 2, 1), make(3, 1, 3), make(3, 3, 1), make(4, 2, 3), make(5, 5, 1)]
    for n in (3, 4, 5, 6, 8, 10, 15, 25, 40, 60):
        for _ in range(2):
            tests.append(make(n))
    N = 100000
    tests.append(make(N))
    tests.append(make(N, 1, N))
    tests.append(make(N, N, 1))
    tests.append(make(N, 54321, 54320))
